#include <assert.h>
#include <gkyl_gyrokinetic_priv.h>
#include <gkyl_loss_cone_mask_gyrokinetic.h>
#include <gkyl_alloc.h>
#include <gkyl_dg_basis_ops.h>

static void
gk_species_fdot_multiplier_write_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  double tm, int frame
)
{
}

static void
gk_species_fdot_multiplier_write_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  double tm, int frame
)
{
  struct timespec wst = gkyl_wall_clock();
  // DG metadata for multiplier.
  struct gkyl_msgpack_map_elem mpe_mult[] = {
    {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 0},
    {.key = "basis_type", .elem_type = GKYL_MP_STRING, .cval = "serendipity"},
    {
      .key = "Description",
      .elem_type = GKYL_MP_STRING,
      .cval = "Function multiplying the distribution time derivative.",
    },
    {.key = "time", .elem_type = GKYL_MP_DOUBLE, .dval = tm},
    {.key = "frame", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = frame}
  };
  int mpe_mult_len = sizeof(mpe_mult) / sizeof(mpe_mult[0]);
  // Package metadata.
  int io_meta_len[] = {gks->io_meta_basic_len, mpe_mult_len, app->gk_geom->io_meta_basic_len};
  const struct gkyl_msgpack_map_elem *io_meta[] = {
    gks->io_meta_basic, mpe_mult, app->gk_geom->io_meta_basic
  };
  struct gkyl_msgpack_data *mt =
    gkyl_msgpack_create_union(sizeof(io_meta_len) / sizeof(int), io_meta_len, io_meta);

  // Write out the combined multiplier.
  const char *fmt = "%s-%s_fdot_multiplier_%d.gkyl";
  int sz = gkyl_calc_strlen(fmt, app->name, gks->info.name, frame);
  char fileNm[sz + 1]; // ensures no buffer overflow
  snprintf(fileNm, sizeof fileNm, fmt, app->name, gks->info.name, frame);

  // Copy data from device to host before writing it out.
  if (app->use_gpu) {
    gkyl_array_copy(fdot_mult->multiplier_host, fdot_mult->multiplier);
  }

  gkyl_comm_array_write(gks->comm, &gks->grid, &gks->local, mt, fdot_mult->multiplier_host, fileNm);
  app->stat.n_io += 1;

  gkyl_msgpack_data_release(mt);

  app->stat.species_diag_io_tm += gkyl_time_diff_now_sec(wst);
}

static void
gk_fdot_multiplier_advance_times_cfl_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  const struct gkyl_array *phi, const struct gkyl_array *f, struct gkyl_array *cflrate
)
{
}

static void
gk_fdot_multiplier_advance_times_cfl_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  const struct gkyl_array *phi, const struct gkyl_array *f, struct gkyl_array *cflrate
)
{
  struct timespec wst = gkyl_wall_clock();

  // Reset combined to 1; each component multiplies its contribution in.
  gkyl_array_clear(fdot_mult->multiplier, 1.0);
  for (int i = 0; i < fdot_mult->num_multipliers; ++i) {
    struct gk_fdot_multiplier_comp *fdmul = &fdot_mult->comp[i];
    fdmul->advance_func(app, gks, fdmul, phi, f, cflrate, fdot_mult->multiplier);
  }
  gkyl_array_scale_by_cell(cflrate, fdot_mult->multiplier);

  app->stat.species_fdot_mult_tm += gkyl_time_diff_now_sec(wst);
}

static void
gk_fdot_multiplier_advance_times_rate_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  const struct gkyl_array *phi, const struct gkyl_array *f, struct gkyl_array *rhs
)
{
}

static void
gk_fdot_multiplier_advance_times_rate_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_fdot_multiplier *fdot_mult,
  const struct gkyl_array *phi, const struct gkyl_array *f, struct gkyl_array *rhs
)
{
  struct timespec wst = gkyl_wall_clock();

  gkyl_array_scale_by_cell(rhs, fdot_mult->multiplier);

  app->stat.species_fdot_mult_tm += gkyl_time_diff_now_sec(wst);
}

static void
gk_species_fdot_multiplier_advance_disabled(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
}

// Advance: multiply combined_multiplier by this component's precomputed buffer array.
static void
gk_species_fdot_multiplier_advance_mult(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  gkyl_array_scale_by_cell(combined_multiplier, fdmul->buffer);
}

// Advance: apply constant scale to combined_multiplier.
static void
gk_species_fdot_multiplier_advance_const(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  gkyl_array_scale(combined_multiplier, fdmul->time_dilation_scale_const);
}

static void
gk_species_fdot_multiplier_advance_loss_cone_mult(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  // Find the potential at the mirror throat.
  gkyl_dg_basis_ops_eval_array_at_coord_comp(
    phi, fdmul->bmag_max_coord, app->basis_on_dev, &app->grid, &app->local, fdmul->phi_m
  );
  gkyl_comm_allreduce(app->comm, GKYL_DOUBLE, GKYL_MAX, 1, fdmul->phi_m, fdmul->phi_m_global);

  // Project the loss cone mask into buffer.
  gkyl_loss_cone_mask_gyrokinetic_advance(
    fdmul->lcm_proj_op, &gks->local, &app->local, phi, fdmul->phi_m_global, fdmul->buffer
  );

  // Apply constant scale factor.
  gkyl_array_scale(fdmul->buffer, fdmul->time_dilation_scale_const);

  // Multiply into combined.
  gkyl_array_scale_by_cell(combined_multiplier, fdmul->buffer);
}

// Compute cell-wise clamp factor min(1, omega_max/cflrate)*scale into combined_multiplier.
// Hopkins, P. F., & Most, E. R. (2025). Time-Dilation Methods for Extreme Multiscale Timestepping Problems. arXiv:2510.09756.
static double
compute_global_array_max(
  const gkyl_gyrokinetic_app *app, const struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *array
)
{
  double local_max;
  if (app->use_gpu) {
#ifdef GKYL_HAVE_CUDA
    gkyl_array_reduce(fdmul->omega_max_local_cu, array, GKYL_MAX);
    gkyl_cu_memcpy(&local_max, fdmul->omega_max_local_cu, sizeof(double), GKYL_CU_MEMCPY_D2H);
#endif
  } else {
    gkyl_array_reduce(&local_max, array, GKYL_MAX);
  }
  double global_max = DBL_MAX;
  gkyl_comm_allreduce_host(app->comm, GKYL_DOUBLE, GKYL_MAX, 1, &local_max, &global_max);
  return global_max;
}

static void
clamp_cflrate_by_omega_max(
  const struct gk_fdot_multiplier_comp *fdmul, const double omega_max,
  const struct gkyl_array *cflrate, struct gkyl_array *combined_multiplier
)
{
  // buffer = min(1, omega_max/cflrate) * time_dilation_scale_const
  gkyl_array_invert_by_cell(fdmul->buffer, cflrate);
  gkyl_array_scale(fdmul->buffer, omega_max);
  gkyl_array_min_by_cell(fdmul->buffer, fdmul->buffer, 1.0);
  gkyl_array_scale(fdmul->buffer, fdmul->time_dilation_scale_const);
  gkyl_array_scale_by_cell(combined_multiplier, fdmul->buffer);
}

static void
gk_species_fdot_multiplier_advance_time_dilation_cfl_dt_omegaH(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  double omega_max = 1.0 / gks->dt_omegaH;
  clamp_cflrate_by_omega_max(fdmul, omega_max, cflrate, combined_multiplier);
}

static void
gk_species_fdot_multiplier_advance_time_dilation_cfl_dt_user_specified(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  double omega_max = 1.0 / fdmul->cfl_dt_min_value;
  clamp_cflrate_by_omega_max(fdmul, omega_max, cflrate, combined_multiplier);
}

static void
gk_species_fdot_multiplier_advance_time_dilation_cfl_dt_set_by_species(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  double omega_max = 1.0 / fdmul->species_dt_is_set_from->dt_cfl_global_ho;
  clamp_cflrate_by_omega_max(fdmul, omega_max, cflrate, combined_multiplier);
}

static void
gk_species_fdot_multiplier_advance_time_dilation_cfl_factor_user_specified(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  double omega_max = compute_global_array_max(app, fdmul, cflrate);
  omega_max = fdmul->cfl_factor_times_omega_max * omega_max;
  clamp_cflrate_by_omega_max(fdmul, omega_max, cflrate, combined_multiplier);
}

static void
gk_species_fdot_multiplier_advance_time_dilation_cfl_f_frac_global(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  gkyl_array_reduce(fdmul->local_max_f, f, GKYL_MAX);
  gkyl_comm_allreduce(
    app->comm, GKYL_DOUBLE, GKYL_MAX, app->basis.num_basis, fdmul->local_max_f, fdmul->global_max_f
  );
  gkyl_dg_array_mask_advance_threshold(fdmul->cfl_mask, fdmul->global_max_f[0]);

  gkyl_dg_array_mask_advance(fdmul->cfl_mask, f);
  gkyl_dg_array_mask_scale_by_cell(fdmul->cfl_mask, cflrate);
  const struct gkyl_array *mask_array = gkyl_dg_array_mask_get_mask(fdmul->cfl_mask);
  double omega_max = compute_global_array_max(app, fdmul, mask_array);
  clamp_cflrate_by_omega_max(fdmul, omega_max, cflrate, combined_multiplier);
}

static void
gk_species_fdot_multiplier_advance_time_dilation_cfl_f_frac_local(
  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_fdot_multiplier_comp *fdmul,
  const struct gkyl_array *phi, const struct gkyl_array *f, const struct gkyl_array *cflrate,
  struct gkyl_array *combined_multiplier
)
{
  gkyl_dg_array_mask_advance(fdmul->cfl_mask, f);
  gkyl_dg_array_mask_scale_by_cell(fdmul->cfl_mask, cflrate);
  const struct gkyl_array *mask_array = gkyl_dg_array_mask_get_mask(fdmul->cfl_mask);
  double omega_max = compute_global_array_max(app, fdmul, mask_array);
  clamp_cflrate_by_omega_max(fdmul, omega_max, cflrate, combined_multiplier);
}

#include <assert.h>
#include <gkyl_gyrokinetic_priv.h>

static void
eval_on_nodes_c2p_position_func(const double *xcomp, double *xphys, void *ctx)
{
  struct gkyl_position_map *gpm = ctx;
  gkyl_position_map_eval_mc2nu(gpm, xcomp, xphys);
}

static void
gk_species_collisionless_flux_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  // Do nothing.
}

static void
gk_species_collisionless_flux_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  // Compute the surface expansion of the phase space flux
  // Note: Each cell stores the *lower* surface expansions of the
  // phase space flux, so local_ext range needed to index the output
  // values of flux_surf even though we only loop over local ranges
  // to avoid evaluating quantities such as geometry in ghost cells
  // where they are not defined.
  gkyl_gk_collisionless_flux_surf(
    gkcls->surf_flux_op, &app->local, &species->local, &app->local_ext, &species->local_ext,
    species->gyro_phi, fin, gkcls->flux_surf, species->cflrate
  );
}

static void
gk_species_collisionless_rhs_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
}

static void
gk_species_collisionless_rhs_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  struct timespec wst = gkyl_wall_clock();

  gkcls->flux_func(app, species, gkcls, fin);

  gkyl_dg_updater_gyrokinetic_advance(gkcls->slvr, &species->local, fin, species->cflrate, rhs);

  gkcls->fdot_scaling(app, species, gkcls, rhs, species->cflrate, &species->local);

  app->stat.species_collisionless_tm += gkyl_time_diff_now_sec(wst);
}

static void
gk_species_collisionless_passive_flux(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  gkyl_gk_collisionless_passive_flux_surf(
    gkcls->passive_surf_flux_op, &app->local, &species->local, &app->local_ext, &species->local_ext,
    fin, gkcls->flux_surf, species->cflrate
  );
}

static void
gk_species_collisionless_passive_rhs(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  struct timespec wst = gkyl_wall_clock();

  gkcls->flux_func(app, species, gkcls, fin);

  gkyl_dg_updater_gyrokinetic_passive_advance(
    gkcls->passive_slvr, &species->local, fin, species->cflrate, rhs
  );

  gkcls->fdot_scaling(app, species, gkcls, rhs, species->cflrate, &species->local);

  app->stat.species_collisionless_tm += gkyl_time_diff_now_sec(wst);
}

static void
gk_species_collisionless_fdot_scaling_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
  struct gkyl_array *rhs, struct gkyl_array *cflrate, struct gkyl_range *rng
)
{
  // Do nothing.
}

static void
gk_species_collisionless_fdot_scaling_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
  struct gkyl_array *rhs, struct gkyl_array *cflrate, struct gkyl_range *rng
)
{
  gkyl_array_scale_range(rhs, gkcls->scale_fac, rng);
  gkyl_array_scale_range(cflrate, gkcls->scale_fac, rng);
}

static void
gk_species_collisionless_write_diags_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls, double tm,
  int frame
)
{
  // Do nothing.
}

static void
gk_species_collisionless_write_diags_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls, double tm,
  int frame
)
{
  struct timespec wst = gkyl_wall_clock();

  // Package metadata.
  gkyl_msgpack_map_elem_set_double(gks->io_meta_phase_len, gks->io_meta_phase, "time", tm);
  gkyl_msgpack_map_elem_set_uint(gks->io_meta_phase_len, gks->io_meta_phase, "frame", frame);
  struct gkyl_msgpack_map_elem desc[] = {{
    .key = "Description",
    .elem_type = GKYL_MP_STRING,
    .cval = "Collisionless flux at cell surface.",
  }};
  int io_meta_len[] = {gks->io_meta_phase_len, app->gk_geom->io_meta_basic_len, 1};
  const struct gkyl_msgpack_map_elem *io_meta[] = {
    gks->io_meta_phase, app->gk_geom->io_meta_basic, desc
  };
  struct gkyl_msgpack_data *mt =
    gkyl_msgpack_create_union(sizeof(io_meta_len) / sizeof(int), io_meta_len, io_meta);

  // Write gkcls->flux_surf
  const char *fmt = "%s-%s_collisionless_surf_flux_%d.gkyl";
  int sz = gkyl_calc_strlen(fmt, app->name, gks->info.name, frame);
  char fileNm[sz + 1]; // ensures no buffer overflow
  snprintf(fileNm, sizeof fileNm, fmt, app->name, gks->info.name, frame);
  gkyl_array_copy(gkcls->flux_surf_ho, gkcls->flux_surf);
  gkyl_comm_array_write(gks->comm, &gks->grid, &gks->local, mt, gkcls->flux_surf_ho, fileNm);

  gkyl_msgpack_data_release(mt);
  app->stat.species_diag_io_tm += gkyl_time_diff_now_sec(wst);
  app->stat.n_io += 1;
}

static void
gk_species_collisionless_init_passive(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
  const bool *is_zero_flux, const enum gkyl_gyrokinetic_bc_type *bctype_conf,
  const struct gkyl_basis *surf_basis
)
{
  int cdim = app->cdim;

  gkcls->flux_surf = mkarr(app->use_gpu, cdim * surf_basis->num_basis, gks->local_ext.volume);

  gkcls->passive_speeds = mkarr(app->use_gpu, cdim * app->basis.num_basis, app->local_ext.volume);
  gkcls->passive_speeds_ho =
    app->use_gpu ? mkarr(false, gkcls->passive_speeds->ncomp, gkcls->passive_speeds->size) :
                   gkyl_array_acquire(gkcls->passive_speeds);

  struct gkyl_eval_on_nodes *speeds_proj = gkyl_eval_on_nodes_inew(&(struct gkyl_eval_on_nodes_inp){
    .grid = &app->grid,
    .basis = &app->basis,
    .num_ret_vals = cdim,
    .eval = gks->info.collisionless.passive_speeds,
    .ctx = gks->info.collisionless.passive_speeds_ctx,
    .c2p_func = eval_on_nodes_c2p_position_func,
    .c2p_func_ctx = app->position_map,
  });
  gkyl_eval_on_nodes_advance(speeds_proj, 0.0, &app->local, gkcls->passive_speeds_ho);
  gkyl_eval_on_nodes_release(speeds_proj);
  gkyl_array_copy(gkcls->passive_speeds, gkcls->passive_speeds_ho);

  // Sync speeds.
  int num_periodic_dir = app->num_periodic_dir;
  gkyl_comm_array_per_sync(
    app->comm, &app->local, &app->local_ext, num_periodic_dir, app->periodic_dirs,
    gkcls->passive_speeds
  );
  gkyl_comm_array_sync(app->comm, &app->local, &app->local_ext, gkcls->passive_speeds);

  gkcls->passive_surf_flux_op = gkyl_gk_collisionless_passive_flux_new(
    &gks->grid, &app->basis, &gks->basis, gkcls->passive_speeds, gks->info.charge, gks->info.mass,
    app->gk_geom, app->dg_geom, app->gk_dg_geom, gks->vel_map, bctype_conf, app->use_gpu
  );

  struct gkyl_dg_gyrokinetic_passive_auxfields passive_aux = {
    .flux_surf = gkcls->flux_surf,
    .speeds = gkcls->passive_speeds,
  };
  gkcls->passive_slvr = gkyl_dg_updater_gyrokinetic_passive_new(
    &gks->grid, &app->basis, &gks->basis, &app->local, &gks->local, is_zero_flux, gks->info.charge,
    gks->info.mass, app->gk_geom, gks->vel_map, &passive_aux, app->use_gpu
  );

  if (gkcls->write_diagnostics) {
    gkyl_msgpack_map_elem_set_double(gks->io_meta_conf_len, gks->io_meta_conf, "time", 0.0);
    gkyl_msgpack_map_elem_set_uint(gks->io_meta_conf_len, gks->io_meta_conf, "frame", 0);
    struct gkyl_msgpack_map_elem desc[] = {{
      .key = "Description",
      .elem_type = GKYL_MP_STRING,
      .cval = "Conf-space passive advection speeds.",
    }};
    int io_meta_len[] = {gks->io_meta_conf_len, app->gk_geom->io_meta_basic_len, 1};
    const struct gkyl_msgpack_map_elem *io_meta[] = {
      gks->io_meta_conf, app->gk_geom->io_meta_basic, desc
    };
    struct gkyl_msgpack_data *mt =
      gkyl_msgpack_create_union(sizeof(io_meta_len) / sizeof(int), io_meta_len, io_meta);

    const char *fmt = "%s-%s_passive_speeds_%d.gkyl";
    int sz = gkyl_calc_strlen(fmt, app->name, gks->info.name, 0);
    char fileNm[sz + 1];
    snprintf(fileNm, sizeof fileNm, fmt, app->name, gks->info.name, 0);
    gkyl_comm_array_write(app->comm, &app->grid, &app->local, mt, gkcls->passive_speeds_ho, fileNm);

    gkyl_msgpack_data_release(mt);
  }

  gkcls->flux_func = gk_species_collisionless_passive_flux;
  gkcls->rhs_func = gk_species_collisionless_passive_rhs;
}

void
gk_species_collisionless_init(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls
)
{
  gkcls->collisionless_id = gks->info.collisionless.type;
  gkcls->write_diagnostics = gks->info.collisionless.write_diagnostics;

  gkcls->write_diags_func = gk_species_collisionless_write_diags_disabled;
  gkcls->flux_func = gk_species_collisionless_flux_disabled;
  gkcls->rhs_func = gk_species_collisionless_rhs_disabled;

  if (gkcls->collisionless_id) {
    int cdim = app->cdim, vdim = gks->info.vdim;
    int pdim = cdim + vdim;

    // Determine which directions are zero-flux. By default
    // we do not have zero-flux boundary conditions in any direction.
    bool is_zero_flux[2 * GKYL_MAX_DIM] = {false};
    for (int dir = 0; dir < app->cdim; ++dir) {
      if (gks->lower_bc[dir].type == GKYL_BC_GK_SPECIES_ZERO_FLUX) {
        is_zero_flux[dir] = true;
      }
      if (gks->upper_bc[dir].type == GKYL_BC_GK_SPECIES_ZERO_FLUX) {
        is_zero_flux[dir + pdim] = true;
      }
    }

    // Need to figure out size of flux_surf by finding size of surface basis set
    struct gkyl_basis surf_basis;
    struct gkyl_basis surf_vpar_basis;
    // Define surface bases
    if (app->poly_order > 1) {
      gkyl_cart_modal_serendip(&surf_basis, pdim - 1, app->poly_order);
    } else {
      gkyl_cart_modal_serendip(&surf_vpar_basis, pdim - 1, app->poly_order);
      if (vdim > 1) {
        gkyl_cart_modal_gkhybrid(&surf_basis, cdim - 1, vdim); // p=2 in vparallel
      } else {
        gkyl_cart_modal_serendip(&surf_basis, pdim - 1, 2); // p=2 in vparallel
      }
    }

    enum gkyl_gyrokinetic_bc_type bctype_conf[2 * GKYL_MAX_CDIM];
    for (int d = 0; d < app->cdim; d++) {
      bctype_conf[d] = gks->lower_bc[d].type;
      bctype_conf[GKYL_MAX_CDIM + d] = gks->upper_bc[d].type;
    }

    if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
      gk_species_collisionless_init_passive(app, gks, gkcls, is_zero_flux, bctype_conf, &surf_basis);
    } else {
      // Allocate arrays to store surface phase space flux.
      gkcls->flux_surf = mkarr(
        app->use_gpu, cdim * surf_basis.num_basis + surf_vpar_basis.num_basis, gks->local_ext.volume
      );

      if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_EM_BPERP) {
        // Parallel component of magnetic vector potential.
        gkcls->apar = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
        gkcls->apardot = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
      } else {
        gkcls->apar = gkyl_array_acquire(app->field->phi_smooth); // Not used.
        gkcls->apardot = gkyl_array_acquire(app->field->phi_smooth); // Not used.
      }

      gkcls->surf_flux_op = gkyl_gk_collisionless_flux_new(
        &gks->grid, &app->basis, &gks->basis, gks->info.charge, gks->info.mass,
        gkcls->collisionless_id, app->gk_geom, app->dg_geom, app->gk_dg_geom, gks->vel_map,
        bctype_conf, app->use_gpu
      );

      struct gkyl_dg_gyrokinetic_auxfields aux_inp = {
        .flux_surf = gkcls->flux_surf,
        .phi = gks->gyro_phi,
        .apar = gkcls->apar,
        .apardot = gkcls->apardot,
      };
      // Create solver.
      gkcls->slvr = gkyl_dg_updater_gyrokinetic_new(
        &gks->grid, &app->basis, &gks->basis, &app->local, &gks->local, is_zero_flux,
        gks->info.charge, gks->info.mass, gkcls->collisionless_id, app->gk_geom, gks->vel_map,
        &aux_inp, app->use_gpu
      );

      gkcls->flux_func = gk_species_collisionless_flux_enabled;
      gkcls->rhs_func = gk_species_collisionless_rhs_enabled;
    }

    gkcls->scale_fac = 1.0; // Not used if scale_factor in input file is not given.
    gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_disabled;
    if (1.0e-16 < fabs(gks->info.collisionless.scale_factor)) {
      gkcls->scale_fac = gks->info.collisionless.scale_factor;
      gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_enabled;
    }

    if (gkcls->write_diagnostics) {
      gkcls->flux_surf_ho = mkarr(false, gkcls->flux_surf->ncomp, gkcls->flux_surf->size);
      gkcls->write_diags_func = gk_species_collisionless_write_diags_enabled;
    }
  }
}

void
gk_species_collisionless_flux(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  gkcls->flux_func(app, species, gkcls, fin);
}

void
gk_species_collisionless_rhs(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  gkcls->rhs_func(app, species, gkcls, fin, rhs);
}

void
gk_species_collisionless_write_diags(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls, double tm,
  int frame
)
{
  gkcls->write_diags_func(app, gks, gkcls, tm, frame);
}

void
gk_species_collisionless_release(
  const struct gkyl_gyrokinetic_app *app, const struct gk_collisionless *gkcls
)
{
  if (gkcls->collisionless_id) {
    gkyl_array_release(gkcls->flux_surf);

    if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
      gkyl_array_release(gkcls->passive_speeds);
      gkyl_array_release(gkcls->passive_speeds_ho);
      gkyl_gk_collisionless_passive_flux_release(gkcls->passive_surf_flux_op);
      gkyl_dg_updater_gyrokinetic_passive_release(gkcls->passive_slvr);
    } else {
      gkyl_array_release(gkcls->apar);
      gkyl_array_release(gkcls->apardot);
      gkyl_gk_collisionless_flux_release(gkcls->surf_flux_op);
      gkyl_dg_updater_gyrokinetic_release(gkcls->slvr);
    }

    if (gkcls->write_diagnostics) {
      gkyl_array_release(gkcls->flux_surf_ho);
    }
  }
}

void
gk_species_collisionless_reset(
  gkyl_gyrokinetic_app *app, double tm, struct gk_species *gks, struct gk_collisionless *gkcls,
  struct gkyl_gyrokinetic_collisionless gkcls_inp
)
{
  gkcls->scale_fac = 1.0;
  gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_disabled;
  if (1.0e-16 < fabs(gkcls_inp.scale_factor)) {
    gks->info.collisionless.scale_factor = gkcls_inp.scale_factor;

    gkcls->scale_fac = gkcls_inp.scale_factor;
    gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_enabled;
  }
}

