}

void
gk_species_collisionless_init(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls
)
{
  gkcls->collisionless_id = gks->info.collisionless.type;
  gkcls->write_diagnostics = gks->info.collisionless.write_diagnostics;

  gkcls->write_diags_func = gk_species_collisionless_write_diags_disabled;
  gkcls->flux_func = gk_species_collisionless_flux_disabled;
  gkcls->rhs_func = gk_species_collisionless_rhs_disabled;

  if (gkcls->collisionless_id) {
    int cdim = app->cdim, vdim = gks->info.vdim;
    int pdim = cdim + vdim;

    // Determine which directions are zero-flux. By default
    // we do not have zero-flux boundary conditions in any direction.
    bool is_zero_flux[2 * GKYL_MAX_DIM] = {false};
    for (int dir = 0; dir < app->cdim; ++dir) {
      if (gks->lower_bc[dir].type == GKYL_BC_GK_SPECIES_ZERO_FLUX) {
        is_zero_flux[dir] = true;
      }
      if (gks->upper_bc[dir].type == GKYL_BC_GK_SPECIES_ZERO_FLUX) {
        is_zero_flux[dir + pdim] = true;
      }
    }

    // Need to figure out size of flux_surf by finding size of surface basis set
    struct gkyl_basis surf_basis;
    struct gkyl_basis surf_vpar_basis;
    // Define surface bases
    if (app->poly_order > 1) {
      gkyl_cart_modal_serendip(&surf_basis, pdim - 1, app->poly_order);
    } else {
      gkyl_cart_modal_serendip(&surf_vpar_basis, pdim - 1, app->poly_order);
      if (vdim > 1) {
        gkyl_cart_modal_gkhybrid(&surf_basis, cdim - 1, vdim); // p=2 in vparallel
      } else {
        gkyl_cart_modal_serendip(&surf_basis, pdim - 1, 2); // p=2 in vparallel
      }
    }

    enum gkyl_gyrokinetic_bc_type bctype_conf[2 * GKYL_MAX_CDIM];
    for (int d = 0; d < app->cdim; d++) {
      bctype_conf[d] = gks->lower_bc[d].type;
      bctype_conf[GKYL_MAX_CDIM + d] = gks->upper_bc[d].type;
    }

    if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
      gk_species_collisionless_init_passive(app, gks, gkcls, is_zero_flux, bctype_conf, &surf_basis);
    } else {
      // Allocate arrays to store surface phase space flux.
      gkcls->flux_surf = mkarr(
        app->use_gpu, cdim * surf_basis.num_basis + surf_vpar_basis.num_basis, gks->local_ext.volume
      );

      if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_EM_BPERP) {
        // Parallel component of magnetic vector potential.
        gkcls->apar = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
        gkcls->apardot = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
      } else {
        gkcls->apar = gkyl_array_acquire(app->field->phi_smooth); // Not used.
        gkcls->apardot = gkyl_array_acquire(app->field->phi_smooth); // Not used.
      }

      gkcls->surf_flux_op = gkyl_gk_collisionless_flux_new(
        &gks->grid, &app->basis, &gks->basis, gks->info.charge, gks->info.mass,
        gkcls->collisionless_id, app->gk_geom, app->dg_geom, app->gk_dg_geom, gks->vel_map,
        bctype_conf, app->use_gpu
      );

      struct gkyl_dg_gyrokinetic_auxfields aux_inp = {
        .flux_surf = gkcls->flux_surf,
        .phi = gks->gyro_phi,
        .apar = gkcls->apar,
        .apardot = gkcls->apardot,
      };
      // Create solver.
      gkcls->slvr = gkyl_dg_updater_gyrokinetic_new(
        &gks->grid, &app->basis, &gks->basis, &app->local, &gks->local, is_zero_flux,
        gks->info.charge, gks->info.mass, gkcls->collisionless_id, app->gk_geom, gks->vel_map,
        &aux_inp, app->use_gpu
      );

      gkcls->flux_func = gk_species_collisionless_flux_enabled;
      gkcls->rhs_func = gk_species_collisionless_rhs_enabled;
    }

    gkcls->scale_fac = 1.0; // Not used if scale_factor in input file is not given.
    gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_disabled;
    if (1.0e-16 < fabs(gks->info.collisionless.scale_factor)) {
      gkcls->scale_fac = gks->info.collisionless.scale_factor;
      gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_enabled;
    }

    if (gkcls->write_diagnostics) {
      gkcls->flux_surf_ho = mkarr(false, gkcls->flux_surf->ncomp, gkcls->flux_surf->size);
      gkcls->write_diags_func = gk_species_collisionless_write_diags_enabled;
    }
  }
}

void
gk_species_collisionless_flux(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  gkcls->flux_func(app, species, gkcls, fin);
}

void
gk_species_collisionless_rhs(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  gkcls->rhs_func(app, species, gkcls, fin, rhs);
}

void
gk_species_collisionless_write_diags(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls, double tm,
  int frame
)
{
  gkcls->write_diags_func(app, gks, gkcls, tm, frame);
}

void
gk_species_collisionless_release(
  const struct gkyl_gyrokinetic_app *app, const struct gk_collisionless *gkcls
)
{
  if (gkcls->collisionless_id) {
    gkyl_array_release(gkcls->flux_surf);

    if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
      gkyl_array_release(gkcls->passive_speeds);
      gkyl_array_release(gkcls->passive_speeds_ho);
      gkyl_gk_collisionless_passive_flux_release(gkcls->passive_surf_flux_op);
      gkyl_dg_updater_gyrokinetic_passive_release(gkcls->passive_slvr);
    } else {
      gkyl_array_release(gkcls->apar);
      gkyl_array_release(gkcls->apardot);
      gkyl_gk_collisionless_flux_release(gkcls->surf_flux_op);
      gkyl_dg_updater_gyrokinetic_release(gkcls->slvr);
    }

    if (gkcls->write_diagnostics) {
      gkyl_array_release(gkcls->flux_surf_ho);
    }
  }
}

void
gk_species_collisionless_reset(
  gkyl_gyrokinetic_app *app, double tm, struct gk_species *gks, struct gk_collisionless *gkcls,
  struct gkyl_gyrokinetic_collisionless gkcls_inp
)
{
  gkcls->scale_fac = 1.0;
  gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_disabled;
  if (1.0e-16 < fabs(gkcls_inp.scale_factor)) {
    gks->info.collisionless.scale_factor = gkcls_inp.scale_factor;

    gkcls->scale_fac = gkcls_inp.scale_factor;
    gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_enabled;
  }
}

item.formatted_output:
  gkyl_gyrokinetic_app *app, struct gk_species *species, const struct gkyl_array *fin,
  struct gkyl_array *rhs, struct gkyl_array **bflux_moms
)
{
  // Gyroaverage the potential if needed.
  species->gyroaverage(app, species, app->field->phi_smooth, species->gyro_phi);

  gkyl_array_clear(species->cflrate, 0.0);
  gkyl_array_clear(rhs, 0.0);

  // Collisionless terms.
  gk_species_collisionless_rhs(app, species, &species->collisionless, fin, rhs);

  // Damping term.
  gk_species_damping_advance(
    app, species, &species->damping, app->field->phi_smooth, fin, species->lte.f_lte, rhs,
    species->cflrate
  );

  // LBO Collisions.
  gk_species_lbo_rhs(app, species, &species->lbo, fin, rhs);

  // BGK collisions.
  gk_species_bgk_rhs(app, species, &species->bgk, fin, rhs);

  // Anomalous diffusion.
  gk_species_anomalous_diff_rhs(app, species, &species->anom_diff, fin, rhs);

  // Line radiation.
  gk_species_radiation_rhs(app, species, &species->rad, fin, rhs);

  // Reactions with charged species.
  gk_species_react_rhs(app, species, &species->react, fin, rhs);

  // Reactions with neutral species.
  gk_species_react_rhs(app, species, &species->react_neut, fin, rhs);

  // BGK source.
  gk_species_source_bgk_rhs(app, species, &species->bgk_src, fin, rhs);

  // Compute and store (in the ghost cell of rhs and in an array in bflux) the boundary fluxes.
  gk_species_bflux_rhs(app, &species->bflux, fin, rhs);

  // Compute moments of the boundary fluxes.
  gk_species_bflux_calc_moms(app, &species->bflux, rhs, bflux_moms);

  // Multiply CFL rate by the df/dt multiplier.
  gk_species_fdot_multiplier_advance_times_cfl(
    app, species, &species->fdot_mult, app->field->phi_smooth, fin, species->cflrate
  );

  // Reduce the CFL frequency and compute stable dt needed by this species.
  app->stat.n_species_omega_cfl += 1;
  struct timespec tm = gkyl_wall_clock();
  gkyl_array_reduce_range(species->omega_cfl, species->cflrate, GKYL_MAX, &species->local);

  double omega_cfl_ho[1];
  if (app->use_gpu) {
    gkyl_cu_memcpy(omega_cfl_ho, species->omega_cfl, sizeof(double), GKYL_CU_MEMCPY_D2H);
  } else {
    omega_cfl_ho[0] = species->omega_cfl[0];
  }

  double dt_out = app->cfl / omega_cfl_ho[0];

  // Apply omega_H constraint on dt.
  species->dt_omegaH = gk_species_omegaH_dt(app, species, fin);
  dt_out = fmin(dt_out, species->dt_omegaH);

  species->dt_cfl_global_ho = dt_out;

  app->stat.species_omega_cfl_tm += gkyl_time_diff_now_sec(tm);
  return dt_out;
}

static double

// Parameters for species reaction
struct gkyl_gyrokinetic_react {
  int num_react; // number of reactions
  // 3 types of reactions supported currently
  // Ionization, Charge exchange, and Recombination
  // GKYL_MAX_SPECIES number of reactions supported per species (8 different reactions)
  struct gkyl_gyrokinetic_react_type react_type[GKYL_MAX_REACT];
  bool write_diagnostics; // Whether to write diagnostics.
};

// Types of scaling operations for a species.
enum gkyl_gk_species_scaling_type {
  GKYL_GK_SPECIES_SCALING_NONE = 0, // No scaling.
  GKYL_GK_SPECIES_SCALING_RECYCLING_IZ_BALANCE, // Balance between recycling and ionization.
  GKYL_GK_SPECIES_SCALING_FIXED_FRACTION, // Maintains fixed fraction relative to another species.
  GKYL_GK_SPECIES_SCALING_BOLTZMANN // n_s = n_{s,sheath}*exp(-q_s*(phi-phi_sheath)/T_s).
};

// Input parameters for scaling a species every time step.
struct gkyl_gyrokinetic_scaling_inp {
  enum gkyl_gk_species_scaling_type type; // Type of scaling operation.

  // Info for GKYL_GK_SPECIES_SCALING_RECYCLING_IZ_BALANCE.
  int num_boundaries; // Number of boundaries.
  int boundaries_dir[GKYL_MAX_CDIM * 2]; // Direction of boundaries.
  enum gkyl_edge_loc boundaries_edge[GKYL_MAX_CDIM * 2]; // Edge of boundaries.
  char impacting_ion_name[128]; // Name of impacting species.
  enum gkyl_ion_type impacting_ion_id; // Type of impacting ion.
  char electron_name[128]; // Name of electron species.
  double recycling_coeff; // Recycling coefficient.

  // Info for GKYL_GK_SPECIES_SCALING_FIXED_FRACTION.
  char ref_species_name[128]; // Name of reference species.
  double fixed_fraction; // Fraction of reference species density.

  bool write_diagnostics; // Whether to write diagnostics.
};

// Parameters in FLR effects.
struct gkyl_gyrokinetic_flr {
  enum gkyl_gk_flr_type type;
  double Tperp; // Perp temperature used to evaluate gyroradius.
  double bmag; // Magnetic field used to evaluate gyroradius. If not provided
  // it'll use B in the center of the domain.
};

struct gkyl_gyrokinetic_correct_inp {
  bool correct_all_moms; // boolean if we are correcting all the moments or only density
  double iter_eps; // error tolerance for moment fixes (density is always exact)
  int max_iter; // maximum number of iteration
  bool use_last_converged; // Boolean for if we are using the results of the iterative scheme
  // *even if* the scheme fails to converge.
};

enum gkyl_gyrokinetic_positivity_type {
  GKYL_GK_POSITIVITY_NONE = 0, // Do not enforce positivity (default).
  GKYL_GK_POSITIVITY_SHIFT, // Shift f to zero if <0 at Gauss-Legendre nodes.
  GKYL_GK_POSITIVITY_MRS_LIMITER // Use the More-Rossmanith-Seal limiter, and shift when needed.
};

struct gkyl_gyrokinetic_positivity {
  enum gkyl_gyrokinetic_positivity_type type; // Type of positivity enforcement algorithm.
  bool
    quasineutrality_rescale; // Whether to rescale this species to enforce quasineutrality in the simulation.
  bool write_diagnostics; // Whether to output diagnostics.
};

enum gkyl_gyrokinetic_damping_type {
  GKYL_GK_DAMPING_NONE = 0,
  GKYL_GK_DAMPING_USER_INPUT,
  GKYL_GK_DAMPING_LOSS_CONE
};

struct gkyl_gyrokinetic_damping {
  // Add a damping term to the RHS of the gyrokinetic equation
  //   df/dt = - rate(z) * f
  // with the function rate(z) being:
  //   - a function given by the user (type = GKYL_PROPORTIONAL_TERM_USER_INPUT).
  //   - I_loss(z) * scale_factor * scale_profile(z), where I_loss(z) is =1 in the loss
  //     cone and 0 in the confined region (type = GKYL_PROPORTIONAL_TERM_LOSS_CONE).
  enum gkyl_gyrokinetic_damping_type type;
  void (*rate_profile)(double t, const double *xn, double *fout, void *ctx);
  void *rate_profile_ctx; // Context for rate_profile function.
  int num_quad; // Number of quadrature points in each direction to use in projecting the rate.
};

// Types of df/dt multipliers: M(x,v,t) modifies df/dt -> M * df/dt.
enum gkyl_gyrokinetic_fdot_multiplier_type {
  GKYL_GK_FDOT_MULTIPLIER_NONE = 0, // No multiplier applied.
  GKYL_GK_FDOT_MULTIPLIER_USER_INPUT, // User-provided static profile M(z) via function pointer.
  GKYL_GK_FDOT_MULTIPLIER_LOSS_CONE, // M=1 in loss cone, M=0 in confined region.
  GKYL_GK_FDOT_MULTIPLIER_CONSTANT, // Dilates time by a fixed constant, time_dilation_scale_const.
  GKYL_GK_FDOT_MULTIPLIER_FIXED_DT, // dt floor from user-specified cfl_dt_min_value.
  GKYL_GK_FDOT_MULTIPLIER_FIXED_FACTOR_TIMES_OMEGA_MAX, // dt floor from user-specified factor times maximum characteristic frequency. Specify cfl_factor_times_omega_max.
  GKYL_GK_FDOT_MULTIPLIER_FIXED_DT_OMEGAH, // dt floor from omega_H, an electrostatic GK wave.
  GKYL_GK_FDOT_MULTIPLIER_DT_SET_BY_SPECIES, // Set the dt floor based on the dt from another species.
  GKYL_GK_FDOT_MULTIPLIER_MASK_F_THRESHOLD, // Dilates time in cells where |J_tot*f| < threshold. Specify f_threshold
  GKYL_GK_FDOT_MULTIPLIER_MASK_F_FRAC_LOCAL, // Dilates time in cells where |J_tot*f| < threshold * local_max. Spatially dependent mask. Specify f_threshold
  GKYL_GK_FDOT_MULTIPLIER_MASK_F_FRAC_GLOBAL // Dilates time in cells where |J_tot*f| < threshold * global_max. Specify f_threshold
};

// Input parameters for a single component of the df/dt multiplier chain.
struct gkyl_gyrokinetic_fdot_multiplier_comp {
  enum gkyl_gyrokinetic_fdot_multiplier_type type; // Type of multiplier (see enum comments above).

  // For USER_INPUT type: function pointer defining M(z).
  void (*profile)(double t, const double *xn, double *fout, void *ctx);
  void *profile_ctx;

  bool cellwise_const; // If true, multiplier is constant within each cell (p=0 basis).
  bool write_diagnostics; // If true, write multiplier array to file.

  // Parameters for time dilation types (FIXED_DT, MASK_F_*):
  double cfl_dt_min_value; // For FIXED_DT: the minimum allowed dt value.
  double f_threshold; // For MASK_F_* types: absolute value (THRESHOLD)
  // or fraction 0-1 (FRAC_LOCAL, FRAC_GLOBAL).
  double
    time_dilation_scale_const; // A constant which multiplies all of fdot and cfl to dilate time. Small number (0,1] so that dt *= 1/time_dilation_scale_const
  double
    cfl_factor_times_omega_max; // For FIXED_FACTOR_TIMES_OMEGA_MAX: the factor multiplied by the maximum characteristic frequency to get the minimum dt value.

  char dt_set_by_species
    [32]; // For DT_SET_BY_SPECIES: the name of the species whose dt we are using to set the maximum dt for this species. e.g. "elc"
};

// Parameters for a chain of df/dt multipliers. Components are applied in order.
struct gkyl_gyrokinetic_fdot_multiplier {
  int num_multipliers;
  struct gkyl_gyrokinetic_fdot_multiplier_comp multiplier[GKYL_MAX_FDOT_MUL];
};

// Parameters for gk species.
struct gkyl_gyrokinetic_species {
  char name[128]; // Species name.

  double charge, mass; // Charge and mass.
  int vdim; // Velocity-space dimensions.
  double lower[GKYL_MAX_VDIM], upper[GKYL_MAX_VDIM]; // Lower, upper bounds of velocity-space.
  int cells[GKYL_MAX_VDIM]; // Velocity-space cells.

  struct gkyl_mapc2p_inp mapc2p;

  bool is_static; // Set to true if species does not change in time.

  struct gkyl_gyrokinetic_positivity positivity; // Positivity enforcement options.

  // Initial conditions using projection routine.
  struct gkyl_gyrokinetic_projection projection;
  // Initial conditions from a file.
  struct gkyl_gyrokinetic_ic_import init_from_file;

  // Ordered list of phase-space fields multiplying df/dt.
  struct gkyl_gyrokinetic_fdot_multiplier time_rate_multiplier;

  double polarization_density; // Density factor in LHS of quasineutrality eqn.

  // Whether to scale the density using a polarization solve
  bool scale_with_polarization;

  int num_diag_moments; // number of diagnostic moments
