// Evaluate initial conditions
// I think ICs should be constructed to match the expander rather than the center
// as the center is quickly filled in the OAP
void
initial_density(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  struct gk_mirror_ctx *app = ctx;
  fout[0] = 1e17;
}

void
initial_upar(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  struct gk_mirror_ctx *app = ctx;
  double z = xn[0];
  double c_s = 7 * sqrt(app->Te0/app->mi);
  if (fabs(z) <= app->Z_m)
  {
    fout[0] = 0.0;
  }
  else
  {
    fout[0] = fabs(z) / z * c_s * tanh(4 * (app->Z_max - app->Z_m) * fabs(fabs(z) - app->Z_m));
  }
}

void
eval_zero(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
  fout[0] = 0.0;
}
  double v_beam = sqrt(E_beam / app->mi);
  double sigma_beam = 2*T_beam/app->mi;

  double source = fmax(gamma0 * exp (-1.0 * (pow(fabs(vpar_midp) - v_beam, 2) + 
                                             pow(vperp - v_beam, 2)) / sigma_beam),1e-20);

  fout[0] = source;
}

void mapc2p_vel_ion(double t, const double *vc, double* GKYL_RESTRICT vp, void *ctx)
{
  struct gk_mirror_ctx *app = ctx;
  double vpar_max_ion = app->vpar_max_ion;
  double mu_max_ion = app->mu_max_ion;

  double cvpar = vc[0], cmu = vc[1];
  double b = 1.4;
  vp[0] = vpar_max_ion*tan(cvpar*b)/tan(b);
  double transition=0.2;
  int power = 3;
  if (cmu < transition) {
    vp[1] = mu_max_ion * pow(transition,power-1) * cmu;
  }
  else {
    vp[1] = mu_max_ion*pow(cmu,power);
  }
}

void mapc2p_vel_elc(double t, const double *vc, double* GKYL_RESTRICT vp, void *ctx)
{
  struct gk_mirror_ctx *app = ctx;
  double mu_max_elc = app->mu_max_elc;
  double vpar_max_elc = app->vpar_max_elc;
  double cvpar = vc[0], cmu = vc[1];
  vp[0] = vpar_max_elc*cvpar;
  vp[1] = mu_max_elc*pow(cmu,4);  // Cubic map in mu.
}

struct gk_mirror_ctx
create_ctx(void)
{
  int cdim = 1, vdim = 2; // Dimensionality.

  // Universal constant parameters.
  double eps0 = GKYL_EPSILON0;
  double mu0 = GKYL_MU0; // Not sure if this is right
  double eV = GKYL_ELEMENTARY_CHARGE;
  double mp = GKYL_PROTON_MASS; // ion mass
  double me = GKYL_ELECTRON_MASS;
  double qi = eV;  // ion charge
  double qe = -eV; // electron charge

  // Plasma parameters.
  double mi = 2.014 * mp;
  double Te0 = 940 * eV;
  double n0 = 3e19;
  double B_p = 0.53; // Bmag at z=0
  double beta = 0.4;
  double tau = pow(B_p, 2.) * beta / (2.0 * mu0 * n0 * Te0) - 1.;
  double Ti0 = tau * Te0;

  // Ion-ion collision freq.
  double nuFrac = 1.0;
  double logLambdaIon = 6.6 - 0.5 * log(n0 / 1e20) + 1.5 * log(Ti0 / eV);
  double nuIon = nuFrac * logLambdaIon * pow(eV, 4.) * n0 /
                 (12 * pow(M_PI, 3. / 2.) * pow(eps0, 2.) * sqrt(mi) * pow(Ti0, 3. / 2.));

  // Geometry parameters.
  double RatZeq0 = 0.10; // Radius of the field line at Z=0.
  double Z_min = -2.5;
  double Z_max =  2.5;
  double mcB = 6.51292;
  double gamma = 0.124904;
  double Z_m = 0.98;

  // POA parameters  
  double alpha_oap = 2e-5;  // Factor multiplying collisionless terms.
  double alpha_fdp = 1.0;
  double tau_oap = 0.1;  // Duration of each phase.
  double tau_fdp = 15e-6;
  double tau_fdp_extra = 3*15e-6;
  int num_cycles = 5; // Number of OAP+FDP cycles to run.

  // Frame counts for each phase type (specified independently)
  int num_frames_oap = 5;        // Frames per OAP phase
  int num_frames_fdp = 5;        // Frames per FDP phase
  int num_frames_fdp_extra = 3*5;  // Frames for the extra FDP phase

  // Whether to evolve the field.
  bool is_static_field_oap = false;
  bool is_static_field_fdp = false;

  // Whether to enable positivity.
  bool is_positivity_enabled_oap = false;
  bool is_positivity_enabled_fdp = false;
  // Type of df/dt multipler.
  enum gkyl_gyrokinetic_fdot_multiplier_type fdot_mult_type_oap = GKYL_GK_FDOT_MULTIPLIER_LOSS_CONE;
  enum gkyl_gyrokinetic_fdot_multiplier_type fdot_mult_type_fdp = GKYL_GK_FDOT_MULTIPLIER_FIXED_FACTOR_TIMES_OMEGA_MAX;

  double cfl_factor_times_omega_max = 1/10.0; // CFL factor for fixed factor times omega max multiplier.

  // Calculate phase structure
        gks->flr_rhoSqD2, flr_weight, app->gk_geom->geo_int.gyyj, 2 * app->basis.num_basis
      );
    }
    // Initialize the factor multiplying the field in the FLR operator.
    gks->flr_kSq = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
    gkyl_array_shiftc(gks->flr_kSq, -pow(sqrt(2.0), app->cdim), 0); // Sets kSq=-1.

    // If domain is not periodic use Dirichlet BCs.
    struct gkyl_poisson_bc flr_bc;
    for (int d = 0; d < app->cdim - 1; d++) {
      struct gkyl_gyrokinetic_bc *bc_lo =
        gk_fetch_bc_with_dir_edge(app->field->info.poisson_bcs, 2 * app->cdim, d, GKYL_LOWER_EDGE);
      if (bc_lo != 0) {
        if (bc_lo->type == GKYL_BC_GK_FIELD_PERIODIC) {
          flr_bc.lo_type[d] = gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_PERIODIC);
        } else {
          flr_bc.lo_type[d] =
            gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_DIRICHLET_VARYING);
        }
      }

      struct gkyl_gyrokinetic_bc *bc_up =
        gk_fetch_bc_with_dir_edge(app->field->info.poisson_bcs, 2 * app->cdim, d, GKYL_UPPER_EDGE);
      if (bc_up != 0) {
        if (bc_up->type == GKYL_BC_GK_FIELD_PERIODIC) {
          flr_bc.up_type[d] = gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_PERIODIC);
        } else {
          flr_bc.up_type[d] =
            gkyl_gyrokinetic_translate_poisson_bc_type(GKYL_BC_GK_FIELD_DIRICHLET_VARYING);
        }
      }
    }
    // Deflated Poisson solve is performed on range assuming decomposition is *only* in z.
    gks->flr_op = gkyl_deflated_fem_poisson_new(
      app->grid, app->basis_on_dev, app->basis, app->local, app->local, gks->flr_rhoSqD2,
      gks->flr_kSq, flr_bc, NULL, app->use_gpu
    );
  } else {
    gks->gyroaverage = gk_species_gyroaverage_disabled;
    gks->m0_gyroavg = gkyl_array_acquire(gks->m0.marr);
    gks->gyro_phi = gkyl_array_acquire(app->field->phi_smooth);
  }

  // Initialize the collisionless solver.
  gks->collisionless = (struct gk_collisionless){};
  gk_species_collisionless_init(app, gks, &gks->collisionless);

  // Initialize an anomalous diffusion term.
  gks->anom_diff = (struct gk_anomalous_diff){};
  gk_species_anomalous_diff_init(app, gks, &gks->anom_diff);

  // Damping term -nu*f on RHS.
  gk_species_damping_init(app, gks, &gks->damping);

  // Function multiplying df/dt.
  gk_species_fdot_multiplier_init(app, gks, &gks->fdot_mult);

  // Allocate data for diagnostic moments.
  int ndm = gks->info.num_diag_moments;
  gks->moms = gkyl_malloc(sizeof(struct gk_species_moment[ndm]));
  for (int m = 0; m < ndm; ++m) {
    gk_species_moment_init(app, gks, &gks->moms[m], gks->info.diag_moments[m], false);
  }

  // Initialize projection routine for initial conditions.
  if (gks->info.init_from_file.type == 0) {
    gk_species_projection_init(app, gks, gks->info.projection, &gks->proj_init);
  } else {
    gk_species_file_import_init(app, gks, gks->info.init_from_file);
  }

    // Reactions (e.g. ionization, recombination charge exchange).
    gk_species_react_cross_moms(app, gk_s, &gk_s->react, fin, fin_neut);
    gk_species_react_cross_moms(app, gk_s, &gk_s->react_neut, fin, fin_neut);

    // Line radiation.
    gk_species_radiation_moms(app, gk_s, &gk_s->rad, fin, fin_neut);

    // Scaling.
    gk_species_scaling_cross_moms(app, gk_s, &gk_s->sca, fin, fin_neut);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    struct gk_neut_species *gk_ns = &app->neut_species[i];

    // Reactions (e.g. ionization, recombination charge exchange).
    gk_neut_species_react_cross_moms(app, gk_ns, &gk_ns->react_neut, fin, fin_neut);

    // Scaling.
    gk_neut_species_scaling_cross_moms(app, gk_ns, &gk_ns->sca, fin, fin_neut);
  }

  // Compute df/dt (not including sources).
  for (int i = 0; i < app->num_species; ++i) {
    struct gk_species *gk_s = &app->species[i];
    double dt1 = gk_species_rhs(app, gk_s, fin[i], fout[i], bflux_out[i]);
    dtmin = fmin(dtmin, dt1);
  }
