  if (gkyl_dg_eqn_is_cu_dev(eqn)) {
    gkyl_gyrokinetic_passive_set_auxfields_cu(eqn->on_dev, auxin);
    return;
  }
#endif
  struct dg_gyrokinetic_passive *gkp = container_of(eqn, struct dg_gyrokinetic_passive, eqn);
